INSERT INTO tb_autor
    (nome, biografia)
VALUES
    ('Machado de Assis', '(1839–1908) foi o maior nome da literatura brasileira e fundador da ABL. Nascido pobre no RJ, superou barreiras sociais com genialidade, ironia e profunda análise psicológica. Obras-primas: Dom Casmurro e Memórias Póstumas.'),
    ('Clarice Lispector', '(1920–1977), nascida na Ucrânia e naturalizada brasileira, revolucionou nossa literatura. Sua prosa introspectiva e psicológica foca nos sentimentos profundos e crises existenciais humanas. Obras-primas: A Hora da Estrela e Laços de Família.'),
    ('Jorge Amado', 'Escritor baiano (1912–2001), foi um dos autores brasileiros mais lidos no mundo. Sua obra celebra a cultura popular, a sensualidade e o povo da Bahia, sempre com forte crítica social. Obras: Capitães da Areia e Dona Flor e Seus Dois Maridos.'),
    ('Guimarães Rosa', 'Escritor e diplomata mineiro (1908–1967), revolucionou a literatura brasileira ao recriar a linguagem popular do sertão com neologismos e reflexões existenciais profundas. Obra principal: Grande Sertão: Veredas.'),
    ('Álvares de Azevedo', 'Poeta paulista (1831–1852), foi o maior expoente do Ultraromantismo no Brasil. Sua obra é marcada pela melancolia, obsessão pela morte, amor idealizado e forte ironia. Obra principal: Noite na Taverna e Lira dos Vinte Anos.');